INSERT INTO `ai_playerbot_texts_german` VALUES ('381', 'suggest_sell', 'Sold almost everything today. Still have %item_formatted_link for %cost_gold.', '0', '0', '', 'Vendu presque tout aujourd\'hui. Vous avez encore %item_formatted_link pour %cost_gold', 'Habe heute fast alles verkauft. Habe noch %item_formatted_link für %cost_gold.', '', '', 'Se vendió casi todo hoy. Todavía tengo %item_formatted_link por %cost_gold.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('382', 'suggest_sell', 'What use for trade chat? Of course to sell %item_formatted_link for %cost_gold.', '0', '0', '', 'A quoi sert le tchat commercial? Bien sûr pour vendre %item_formatted_link pour %cost_gold', 'Wozu Handels-Chat? Natürlich, um %item_formatted_link für %cost_gold zu verkaufen.', '', '', '¿De qué sirve el chat comercial? Por supuesto, para vender %item_formatted_link por %cost_gold.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('383', 'suggest_sell', 'Can anyone beat the price of %cost_gold for %item_formatted_link?', '0', '0', '', 'Quelqu\'un peut-il battre le prix de %cost_gold pour %item_formatted_link ?', 'Kann jemand den Preis von %cost_gold für %item_formatted_link schlagen?', '', '', '¿Alguien puede superar el precio de %cost_gold por %item_formatted_link?', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('384', 'suggest_sell', 'Wanna stop trade chat? Just buy %item_formatted_link? For %cost_gold!', '0', '0', '', 'Vous voulez arrêter le chat commercial? Vous venez d\'acheter %item_formatted_link ? Pour %cost_gold !', 'Möchtest du den Handels-Chat stoppen? Kauf einfach %item_formatted_link? Für %cost_gold!', '', '', '¿Quieres detener el chat comercial? ¿Solo compra %item_formatted_link? ¡Por el oro!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('385', 'suggest_sell', 'Everybody spams in trade chat. Me too - %cost_gold for %item_formatted_link!', '0', '0', '', 'Tout le monde spamme dans le chat commercial. Moi aussi - %cost_gold pour %item_formatted_link !', 'Jeder spammt im Handels-Chat. Ich auch – %cost_gold für %item_formatted_link!', '', '', 'Todo el mundo envía spam en el chat y yo también! ¡%item_formatted_link por %cost_gold!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('386', 'suggest_sell', 'Is %item_formatted_link any use? Just selling it for %cost_gold.', '0', '0', '', '%item_formatted_link est-il utile? Je le vends juste pour %cost_gold', 'Ist %item_formatted_link nützlich? Verkaufe es nur für %cost_gold.', '', '', '¿Es %item_formatted_link útil? Solo lo vendo por %cost_gold.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('387', 'suggest_sell', 'I have %item_formatted_link ready to sell you for %cost_gold.', '0', '0', '', 'J\'ai %item_formatted_link prêt à vous vendre pour %cost_gold', 'Ich habe %item_formatted_link bereit, um es dir für %cost_gold zu verkaufen.', '', '', 'Tengo %item_formatted_link listo a la venta por %cost_gold.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('388', 'suggest_sell', 'Did nothing yesterday but have got %item_formatted_link. Selling it for %cost_gold.', '0', '0', '', 'Je n\'ai rien fait hier mais j\'ai %item_formatted_link Je le vends pour %cost_gold', 'Gestern nichts gemacht, aber %item_formatted_link bekommen. Verkaufe es für %cost_gold.', '', '', 'No hice nada ayer pero consegu\'i %item_formatted_link. Lo vendo por %cost_gold.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('389', 'suggest_sell', 'Farmed yesterday and got %item_formatted_link. Anyone wtb for %cost_gold?', '0', '0', '', 'Farmé hier et obtenu %item_formatted_link Quelqu\'un cherche à acheter pour %cost_gold ?', 'Gestern gefarmt und %item_formatted_link bekommen. Möchte jemand es für %cost_gold kaufen?', '', '', 'Ayer farmee y conseguí mucho %item_formatted_link. ¿Alguien lo quiere comprar por %cost_gold?', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('390', 'suggest_sell', 'Bought %item_formatted_link yesterday. Anyone needs it for %cost_gold?', '0', '0', '', 'Acheté %item_formatted_link hier. Quelqu\'un en a besoin pour %cost_gold ?', '%item_formatted_link gestern gekauft. Braucht es jemand für %cost_gold?', '', '', 'Ayer compré %item_formatted_link. ¿Alguien lo quiere por %cost_gold?', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('391', 'suggest_sell', 'Who asked for %item_formatted_link? The price is the same - %cost_gold.', '0', '0', '', 'Qui a demandé %item_formatted_link ? Le prix est le même - %cost_gold', 'Wer hat nach %item_formatted_link gefragt? Der Preis ist derselbe – %cost_gold.', '', '', '¿Quién pidió %item_formatted_link? El precio es el mismo: %cost_gold.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('392', 'suggest_sell', 'I sill have %item_formatted_link. WTB for %cost_gold?', '0', '0', '', 'J\'ai toujours %item_formatted_link. Cherche à acheter pour %cost_gold ?', 'Ich habe immer noch %item_formatted_link. WTB für %cost_gold?', '', '', 'Todavía tengo %item_formatted_link. ¿Alguien lo compra por %cost_gold?', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('393', 'suggest_sell', 'I used to have more than %item_formatted_link. Now needs to sell it for %cost_gold.', '0', '0', '', 'J\'avais plus de %item_formatted_link Il faut maintenant le vendre pour %cost_gold', 'Früher hatte ich mehr als %item_formatted_link. Jetzt muss ich es für %cost_gold verkaufen.', '', '', 'Solía tener más de %item_formatted_link. Ahora necesito venderlo por %cost_gold.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('394', 'suggest_sell', 'I wish I have more than %item_formatted_link. You could buy it for %cost_gold anyways.', '0', '0', '', 'J\'aimerais avoir plus de %item_formatted_link . Vous pouvez l\'acheter pour %cost_gold de toute façon.', 'Ich wünschte, ich hätte mehr als %item_formatted_link. Du könntest es trotzdem für %cost_gold kaufen.', '', '', 'Desearía tener más de %item_formatted_link. Podrías comprarlo por %cost_gold de todos modos.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('395', 'suggest_sell', 'What use for your gold? To buy my %item_formatted_link for %cost_gold.', '0', '0', '', 'A quoi sert votre or ? Pour acheter mon %item_formatted_link pour %cost_gold', 'Wofür dein Gold? Um mein %item_formatted_link für %cost_gold zu kaufen.', '', '', '¿De qué sirve tu oro? Para comprar mi %item_formatted_link por %cost_gold.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('396', 'suggest_sell', 'Please spare some gold for me. You can buy %item_formatted_link for %cost_gold.', '0', '0', '', 'S\'il vous plaît, épargnez-moi de l\'or. Vous pouvez acheter %item_formatted_link pour %cost_gold', 'Bitte spare etwas Gold für mich. Du kannst %item_formatted_link für %cost_gold kaufen.', '', '', 'Por favor, dame algo de oro. Puedes comprar %item_formatted_link por %cost_gold.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('397', 'suggest_sell', 'Is %cost_gold is a good price for %item_formatted_link?', '0', '0', '', '%cost_gold est-il un bon prix pour %item_formatted_link ?', 'Ist %cost_gold ein guter Preis für %item_formatted_link?', '', '', '¿%cost_gold es un buen precio para %item_formatted_link?', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('398', 'suggest_sell', 'Just bought yesterday %item_formatted_links, but do not need it anymore. Anyone wants for %cost_gold?', '0', '0', '', 'Je viens d\'acheter hier %item_formatted_links , mais je n\'en ai plus besoin. Quelqu\'un veut %cost_gold ?', 'Habe gestern %item_formatted_links gekauft, brauche es aber nicht mehr. Möchte jemand es für %cost_gold?', '', '', 'Ayer compré %item_formatted_link, pero ya no los necesito. ¿Alguien lo quiere por %cost_gold?', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('399', 'suggest_sell', 'I am going to post %item_formatted_link on the AH but you can buy it now cheaper just for %cost_gold.', '0', '0', '', 'Je vais poster %item_formatted_link à l\'hôtel des ventes mais vous pouvez l\'acheter maintenant moins cher juste pour %cost_gold', 'Ich werde %item_formatted_link im AH posten, aber du kannst es jetzt günstiger für nur %cost_gold kaufen.', '', '', 'Voy a poner %item_formatted_link en la casa de subastas pero puedes comprarlo ahora más barato solo por %cost_gold.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('400', 'suggest_sell', 'Why the #!@ have I bought %item_formatted_link? Anyone needs it for %cost_gold?', '0', '0', '', 'Pourquoi ai-je acheté le #!@ %item_formatted_link ? Quelqu\'un en a besoin pour %cost_gold ?', 'Warum zum #!@ habe ich %item_formatted_link gekauft? Braucht es jemand für %cost_gold?', '', '', '¿Por qué #!@ he comprado %item_formatted_link? ¿Alguien lo necesita por %cost_gold?', '', '');
