INSERT INTO `ai_playerbot_texts_german` VALUES ('599', 'taunt', 'Bite me, <target>!', '0', '0', '', 'Mords moi, <target>!', 'Beiß mich, <target>!', '', '', '¡Muérdeme, <target>!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('600', 'taunt', 'Hey <target>! Guess what your mom said last night!', '0', '0', '', 'Hey <target>! Devine ce que ta mère a dit hier soir!', 'Hey <target>! Weißt du, was deine Mutter letzte Nacht gesagt hat!', '', '', '¡Oye, <target>! ¡Adivina lo que me dijo tu madre anoche!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('601', 'taunt', '<target>, you\'re so ugly you couldn\'t score in a monkey whorehouse with a bag of bananas!', '0', '0', '', '<target>, tu es si moche que tu ne pourrais pas marquer dans un bordel de singes avec un sac de bananes!', '<target>, du bist so hässlich, du würdest nicht mal in einem Affenbordell mit einem Sack Bananen landen!', '', '', '<target>, ¡eres tan feo que no podrías anotar en un burdel de monos con una bolsa de plátanos!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('602', 'taunt', 'Shut up <target>, you\'ll never be the man your mother is!!', '0', '0', '', 'Tais-toi <target>, tu ne seras jamais l\'homme qu\'est ta mère!!', 'Halt den Mund <target>, du wirst nie der Mann sein, der deine Mutter ist!!', '', '', 'Cállate <target>, ¡nunca serás el hombre que es tu madre!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('603', 'taunt', 'Your mother was a hampster and your father smelt of elderberries!!!!', '0', '0', '', 'Ta mère était un hamster et ton père sentait le sureau!!!!', 'Deine Mutter war ein Hamster und dein Vater roch nach Holunderbeeren!!!!', '', '', 'Tu madre era un hámster y tu padre olía a bayas de saúco!!!!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('604', 'taunt', 'I don\'t want to talk to you no more, you empty headed animal food trough wiper!!!', '0', '0', '', 'Je ne veux plus te parler, espèce d\'essuyeur d\'abreuvoirs pour animaux tête vide!!!', 'Ich will nicht mehr mit dir reden, du leerer, dummer Futtertrogwischer!!!', '', '', '¡¡No quiero hablar más contigo, limpiaparabrisas de cabeza vacía!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('605', 'taunt', 'I fart in your general direction!!!', '0', '0', '', 'Je pète dans votre direction générale!!!', 'Ich furze in deine allgemeine Richtung!!!', '', '', '¡¡Me tiro un pedo en tu dirección general!!!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('606', 'taunt', 'Go and boil your bottom, you son of a silly person!!!', '0', '0', '', 'Va te faire cuire le cul, fils d\'idiot!!!', 'Geh und koch deinen Hintern aus, du Sohn einer lächerlichen Person!!!', '', '', '¡Ve y hierve tu trasero, hijo de una persona tonta!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('607', 'taunt', 'What are you going to do <target>, bleed on me? HAVE AT YOU!', '0', '0', '', 'Qu\'est ce que tu vas faire <target>, saigner sur moi? A VOUS!', 'Was willst du tun, <target>, an mir verbluten? AUF GEHT\'S!', '', '', '¿Qué vas a hacer <target>, llorar?', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('608', 'taunt', 'M-O-O-N! That spells aggro!', '0', '0', '', 'PUNAISE! Ce sort aggro!', 'M-O-O-N! Das buchstabiert Aggro!', '', '', '¡LUNA! ¡Eso deletrea agresividad!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('609', 'taunt', 'You\'re about as useful as a one-legged man in an butt kicking contest.', '0', '0', '', 'Tu es à peu près aussi utile qu\'un homme unijambiste dans un concours de coups de pied au cul.', 'Du bist ungefähr so nützlich wie ein einbeiniger Mann in einem Hintern-Tret-Wettbewerb.', '', '', 'Eres tan útil como un hombre con una sola pierna en un concurso de patadas en el culo.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('610', 'taunt', 'Hey <target>! Stop hitting on them, they\'re not your type. They aren\'t inflatable.', '0', '0', '', 'Hey <target>! Arrête de les draguer, ce n\'est pas ton genre. Ils ne sont pas gonflables.', 'Hey <target>! Hör auf, mit ihnen zu flirten, sie sind nicht dein Typ. Sie sind nicht aufblasbar.', '', '', '¡Oye, <target>! Deja de coquetear con ellos, no son tu tipo. No son inflables.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('611', 'taunt', '<target> you\'re so far outta your league, you\'re playing a different sport.', '0', '0', '', '<target> vous êtes tellement hors de votre ligue que vous pratiquez un sport différent.', '<target>, du bist so weit außerhalb deiner Liga, dass du einen anderen Sport spielst.', '', '', '<target> estás tan lejos de tu liga, estás jugando un deporte diferente.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('612', 'taunt', 'You made a big mistake today <target>, you got out of bed.', '0', '0', '', 'Tu as fait une grosse erreur aujourd\'hui <target>, tu es sorti du lit.', 'Du hast heute einen großen Fehler gemacht, <target>, du bist aus dem Bett gestiegen.', '', '', 'Cometiste un gran error hoy <target>, te levantaste de la cama.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('613', 'taunt', 'I wanna try turning into a horse, but I need help. I\'ll be the front, you be yourself.', '0', '0', '', 'Je veux essayer de me transformer en cheval, mais j\'ai besoin d\'aide. Je serai devant, tu seras toi-même.', 'Ich möchte versuchen, mich in ein Pferd zu verwandeln, aber ich brauche Hilfe. Ich bin vorne, du bleibst du selbst.', '', '', 'Quiero intentar convertirme en un caballo, pero necesito ayuda. Yo seré el frente, tú mismo.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('614', 'taunt', 'Can I borrow your face for a few days? My butt is going on holiday....', '0', '0', '', 'Puis-je emprunter votre visage pendant quelques jours? Mon cul part en vacances....', 'Kann ich dein Gesicht für ein paar Tage ausleihen? Mein Hintern macht Urlaub...', '', '', '¿Me prestas tu cara por unos días? Mi culo se va de vacaciones...', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('615', 'taunt', 'I\'d like to give you a going away present... First you do your part.', '0', '0', '', 'J\'aimerais vous offrir un cadeau de départ... D\'abord, donnes ta part.', 'Ich würde dir gerne ein Abschiedsgeschenk geben... aber erst machst du deinen Teil.', '', '', 'Me gustaría darte un regalo de despedida... Primero haz tu parte.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('616', 'taunt', 'Before you came along we were hungry, Now we\'re just fed up.', '0', '0', '', 'Avant que tu n\'arrives nous avions faim, maintenant nous en avons juste marre.', 'Bevor du kamst, hatten wir Hunger. Jetzt sind wir nur noch genervt.', '', '', 'Antes de que llegaras teníamos hambre, ahora estamos hartos', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('617', 'taunt', 'I like you. People say I have no taste, but I like you.', '0', '0', '', 'Je t\'aime bien. Les gens disent que je n\'ai pas de goût, mais je t\'aime bien.', 'Ich mag dich. Die Leute sagen, ich habe keinen Geschmack, aber ich mag dich.', '', '', 'Me gustas. La gente dice que no tengo gusto, pero me gustas.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('618', 'taunt', 'I think you have an inferiority complex, but that\'s okay, it\'s justified.', '0', '0', '', 'Je pense que tu as un complexe d\'infériorité, mais il n\'y a pas de problème, c\'est justifié.', 'Ich glaube, du hast einen Minderwertigkeitskomplex, aber das ist okay, er ist gerechtfertigt.', '', '', 'Creo que tienes complejo de inferioridad, pero está bien, está justificado', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('619', 'taunt', 'Hence rotten thing! Or I shall shake thy bones out of thy garments.', '0', '0', '', 'Par conséquent chose pourrie! Je vais secouer tes os de tes vêtements.', 'Fort mit dir, du verdorbenes Ding! Oder ich werde dir die Knochen aus deinen Kleidern schütteln.', '', '', '¡Por lo tanto, cosa podrida! o te sacudiré los huesos de las vestiduras.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('620', 'taunt', 'I can\'t believe I\'m wasting my time with you!', '0', '0', '', 'Je n\'arrive pas à croire que je perds mon temps avec toi!', 'Ich kann nicht glauben, dass ich meine Zeit mit dir verschwende!', '', '', '¡No puedo creer que estoy perdiendo el tiempo contigo!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('621', 'taunt', 'I love it when someone insults me, it means I don\'t have to be nice anymore.', '0', '0', '', 'J\'adore quand quelqu\'un m\'insulte, ça veut dire que je n\'ai plus besoin d\'être gentil.', 'Ich liebe es, wenn mich jemand beleidigt, das bedeutet, ich muss nicht mehr nett sein.', '', '', 'Me encanta cuando alguien me insulta, significa que ya no tengo que ser amable', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('622', 'taunt', 'Thou leathern-jerkin, crystal-button, knot-pated, agatering, puke-stocking, caddis-garter, smooth-tongue, Spanish pouch!', '0', '0', '', 'Toi l\'agent fédéral, pourpoint en cuir, bouton de cristal, anneau d\'agate, bas vomi, jarretière caddis, pochette espagnole!', 'Du lederne Weste, Kristallknopf, knotiger Dickkopf, Spötter, Kotzstrumpf, Cadis-Strumpfband, glatte Zunge, spanischer Beutel!', '', '', '¡Tú, jubón de cuero, botón de cristal, anudado, ágata, medias de vómito, liga de caddis, lengua suave, bolsa española!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('623', 'taunt', 'Thou qualling bat-fowling malt-worm!', '0', '0', '', 'Toi qualificatif de chauve-souris qui chasse le ver de malt!', 'Du winselnder Bat-Fowling-Malz-Wurm!', '', '', '¡Tú, gusano de malta cazador de murciélagos!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('624', 'taunt', 'Thou art truely an idol of idiot-worshippers!', '0', '0', '', 'Tu es vraiment une idole d\'adorateurs d\'idiots!', 'Du bist wirklich ein Idol für Idiotenanbeter!', '', '', '¡Eres verdaderamente un ídolo de los adoradores de idiotas!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('625', 'taunt', 'Thou misbegotten knotty-pated wagtail!', '0', '0', '', 'Tu es une bergeronnette printanière mal engendrée!', 'Du missratener knotiger Schwanzwedler!', '', '', '¡Maldito lavandero nudoso!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('626', 'taunt', 'Thou whoreson mandrake, thou art fitter to be worn in my cap than to wait at my heels!', '0', '0', '', 'Toi putain de mandragore, tu es plus apte à être porté dans ma casquette qu\'à attendre sur mes talons!', 'Du Mandragora-Nachkomme, du bist besser geeignet, in meinem Hut getragen zu werden, als an meinen Fersen zu warten!', '', '', '¡Hijo de puta mandrágora, eres mejor para que te lleve en mi gorra que para que me pise los talones!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('627', 'taunt', 'You! You scullion! You rampallian! You fustilarian! I\'ll tickle your catastrophe!', '0', '0', '', 'Toi ! Espèce de marmiton ! Espèce de rampallian ! Espèce de fusilier ! Je vais chatouiller ta catastrophe!', 'Du! Du Küchenjunge! Du Gauner! Du Stümper! Ich werde deine Katastrophe kitzeln!', '', '', '¡Tú! ¡Scullion! ¡Ramaliano! ¡Fustilarista! ¡Te haré cosquillas en tu catástrofe!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('628', 'taunt', 'Oh <target>! Thou infectious ill-nurtured flax-wench!', '0', '0', '', 'Oh <target>! Tu es contagieuse et mal nourrie!', 'Oh <target>! Du ansteckende, schlecht erzogene Flachspuppe!', '', '', '¡Oh, <target>! ¡Tú, contagiosa moza del lino mal educada!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('629', 'taunt', 'We leak in your chimney, <target>!', '0', '0', '', 'On a une fuite dans votre cheminée, <target>!', 'Wir lecken in deinem Schornstein, <target>!', '', '', '¡Tenemos una fuga en tu chimenea, <target>!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('630', 'taunt', 'Oh thou bootless fen-sucked canker-blossom!', '0', '0', '', 'Oh toi, fleur de chancre sucée par les marais sans botte!', 'Oh du nutzloser, sumpfgesogener Krebsblüte!', '', '', '¡Oh tú, flor de cancro chupada por el pantano sin botas!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('631', 'taunt', 'Were I like thee I\'d throw away myself!', '0', '0', '', 'Si j\'étais comme toi, je me jetterais!', 'Wäre ich wie du, würde ich mich selbst wegwerfen!', '', '', '¡Si yo fuera como tú, me tiraría a la basura!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('632', 'taunt', 'O teach me <target>, how I should forget to think!', '0', '0', '', 'O apprends-moi <target>, comme je devrais oublier de penser!', 'Oh lehre mich, <target>, wie ich das Denken vergessen soll!', '', '', '¡Oh, enséñame <target>, cómo debo olvidarme de pensar!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('633', 'taunt', 'Truly thou art damned, like an ill-roasted egg, all on one side!', '0', '0', '', 'Vraiment tu es damné, comme un œuf mal rôti, tout d\'un côté!', 'Wahrlich, du bist verdammt, wie ein schlecht geröstetes Ei, alles auf einer Seite!', '', '', '¡Verdaderamente estás condenado, como un huevo mal asado, todo de un lado!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('634', 'taunt', 'You starvelling, you eel-skin, you dried neat\'s-tongue, you bull\'s-pizzle, you stock-fish- O for breath to utter what is like thee!! -you tailor\'s-yard, you sheath, you bow-case, you vile standing tuck!', '0', '0', '', 'Toi affamé, espèce de peau d\'anguille, ta langue bien séchée, espèce de taureau, poisson séché, O pour le souffle de dire ce qui te ressemble !! -espèce de vergue de tailleur, espèce de fourreau, espèce d\'étui à archet, vil tuck debout', 'Du Hungerleider, du Aalknochen, du getrocknete Ochsenzunge, du Ochsenpimmel, du Stockfisch – O für Atem, um auszusprechen, was dir gleicht!! – du Schneidermaß, du Scheide, du Bogentasche, du abscheulicher stehender Degen!', '', '', 'Estás muerto de hambre, piel de anguila, te secaste la lengua limpiamente, toro-pizzle, pescado-O para respirar pronunciar lo que es como tú !! ¡Tú, sastrería, vaina, estuche de arco, vil flaco de pie!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('635', 'taunt', 'Fie! Drop thee into the rotten mouth of Death!', '0', '0', '', 'Fi ! Jette-toi dans la bouche pourrie de la Mort!', 'Pfui! Lass dich in den fauligen Mund des Todes fallen!', '', '', '¡Fie! ¡Déjate caer en la podrida boca de la Muerte!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('636', 'taunt', '<target>, you are a fishmonger!', '0', '0', '', '<target>, vous êtes poissonnier!', '<target>, du bist ein Fischhändler!', '', '', '<target>, ¡eres un pescadero!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('637', 'taunt', 'I shall live to knock thy brains out!', '0', '0', '', 'Je vivrai pour te faire sauter la cervelle!', 'Ich werde leben, um dir das Gehirn auszuschlagen!', '', '', '¡Viviré para romperte los sesos!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('638', 'taunt', 'Most shallow are you, <target>!! Thou art worms-meat in respect of a good piece of flesh, indeed!!', '0', '0', '', 'Tu es très superficiel, <target>!! Tu es de la viande de vers par rapport à un bon morceau de chair, en effet!!', 'Du bist so oberflächlich, <target>!! Du bist Wurmfutter im Vergleich zu einem guten Stück Fleisch, wirklich!!', '', '', '¡¡Eres el más superficial, <target>!! ¡Eres carne de gusano con respecto a un buen trozo de carne, de hecho!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('639', 'taunt', 'Vile wretch! O <target>, thou odiferous hell-hated pignut!', '0', '0', '', 'Misérable ! O <target>, toi, ignoble cochon de l\'enfer!', 'Elender Schuft! O <target>, du stinkender, höllengehasster Erdnuss!', '', '', '¡Miserable vil! ¡Oh, <target>, fétido cerdo odiado por el infierno!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('640', 'taunt', '<target>! Thy kiss is as comfortless as frozen water to a starved snake!', '0', '0', '', '<target>! Ton baiser est aussi désagréable que de l\'eau gelée pour un serpent affamé!', '<target>! Dein Kuss ist so trostlos wie gefrorenes Wasser für eine ausgehungerte Schlange!', '', '', '<target>! ¡Tu beso es tan desconsolador como el agua helada para una serpiente hambrienta!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('641', 'taunt', 'I scorn you, scurvy companion. What, you poor, base, rascally, cheating, lack-linen mate! Away, you moldy rogue, away!', '0', '0', '', 'Je te méprise, compagnon du scorbut. Quoi, pauvre, bas, coquin, tricheur, camarade en manque de linge ! Partez, espèce de voyou moisi, partez!', 'Ich verachte dich, schäbiger Gefährte. Was, du armer, gemeiner, betrügerischer, leinenloser Kumpan! Weg, du schimmeliger Schurke, weg!', '', '', 'Te desprecio, compañero escorbuto. ¡Qué, pobre, vil, pícaro, tramposo, compañero falto de lino! ¡Fuera, mohoso granuja, fuera!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('642', 'taunt', 'Out of my sight! Thou dost infect my eyes <target>!', '0', '0', '', 'Hors de ma vue! Tu infectes mes yeux <target>!', 'Raus aus meinem Blickfeld! Du infizierst meine Augen, <target>!', '', '', '¡Fuera de mi vista! ¡Me infectas los ojos <target>!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('643', 'taunt', 'PLAY TIME!!!!', '0', '0', '', 'RÉCRÉATION!!!!', 'SPIELZEIT!!!!', '', '', '¡¡¡HORA DE JUGAR!!!!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('644', 'taunt', 'None shall pass!', '0', '0', '', 'Personne ne passera!', 'Keiner darf passieren!', '', '', '¡Ninguno pasará!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('645', 'taunt', 'We\'re under attack! A vast, ye swabs! Repel the invaders!', '0', '0', '', 'Nous sommes attaqués ! Un vaste écouvillons! Repoussez les envahisseurs!', 'Wir werden angegriffen! Auf, ihr Schurken! Vertreibt die Eindringlinge!', '', '', '¡Estamos bajo ataque! ¡Un vasto, hisopos! ¡Repeler a los invasores!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('646', 'taunt', 'None may challenge the Brotherhood!', '0', '0', '', 'Personne ne peut défier la Confrérie!', 'Niemand darf die Bruderschaft herausfordern!', '', '', '¡Nadie puede desafiar a la Hermandad!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('647', 'taunt', 'Foolsss...Kill the one in the dress!', '0', '0', '', 'Foolsss... Tuez celui qui porte la robe!', 'Narren... Tötet den in der Robe!', '', '', 'Tontosss... ¡Matad al del vestido!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('648', 'taunt', 'I\'ll feed your soul to Hakkar himself! ', '0', '0', '', 'Je donnerai ton âme à Hakkar lui-même! ', 'Ich werde deine Seele Hakkar selbst zum Fraß vorwerfen!', '', '', '¡Le daré de comer con tu alma al mismísimo Hakkar! ', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('649', 'taunt', 'Pride heralds the end of your world! Come, mortals! Face the wrath of the <randomfaction>!', '0', '0', '', 'La fierté annonce la fin de votre monde ! Venez, mortels ! Affrontez la colère des <randomfaction>!', 'Stolz verkündet das Ende eurer Welt! Kommt, Sterbliche! Stellt euch dem Zorn des <randomfaction>!', '', '', '¡El orgullo anuncia el fin de tu mundo! ¡Venid, mortales! ¡Enfréntate a la ira de la <facción aleatoria>!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('650', 'taunt', 'All my plans have led to this!', '0', '0', '', 'Tous mes plans ont mené à cela!', 'Alle meine Pläne haben zu diesem Moment geführt!', '', '', '¡Todos mis planes me han llevado a esto!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('651', 'taunt', 'Ahh! More lambs to the slaughter!', '0', '0', '', 'Ahhh ! Plus d\'agneaux à l\'abattoir!', 'Ahh! Mehr Lämmer für die Schlachtbank!', '', '', '¡Ahh! ¡Más corderos al matadero!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('652', 'taunt', 'Another day, another glorious battle!', '0', '0', '', 'Un autre jour, une autre bataille glorieuse!', 'Ein weiterer Tag, eine weitere glorreiche Schlacht!', '', '', '¡Otro día, otra batalla gloriosa!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('653', 'taunt', 'So, business... or pleasure?', '0', '0', '', 'Alors, affaires... ou plaisir?', 'Also, Geschäft... oder Vergnügen?', '', '', 'Entonces, ¿negocios... o placer?', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('654', 'taunt', 'You are not prepared!', '0', '0', '', 'Vous n\'êtes pas prêt!', 'Ihr seid nicht vorbereitet!', '', '', '¡No estás preparado!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('655', 'taunt', 'The <randomfaction>\'s final conquest has begun! Once again the subjugation of this world is within our grasp. Let none survive! ', '0', '0', '', 'La conquête finale de la <randomfaction> a commencé ! Une fois de plus, l\'assujettissement de ce monde est à notre portée. Que personne ne survive!', 'Die endgültige Eroberung der <randomfaction> hat begonnen! Wieder einmal ist die Unterwerfung dieser Welt in unserer Reichweite. Lasst keinen am Leben!', '', '', '¡La conquista final de <randomfaction> ha comenzado! Una vez más, la subyugación de este mundo está a nuestro alcance. ¡Que nadie sobreviva! ', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('656', 'taunt', 'Your death will be a painful one. ', '0', '0', '', 'Ta mort sera douloureuse.', 'Dein Tod wird ein schmerzhafter sein.', '', '', 'Tu muerte será dolorosa. ', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('657', 'taunt', 'Cry for mercy! Your meaningless lives will soon be forfeit. ', '0', '0', '', 'Crie miséricorde ! Vos vies insignifiantes seront bientôt perdues.', 'Fleht um Gnade! Eure bedeutungslosen Leben werden bald verwirkt sein.', '', '', '¡Llora por piedad! Sus vidas sin sentido pronto se perderán. ', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('658', 'taunt', 'Abandon all hope! The <randomfaction> has returned to finish what was begun so many years ago. This time there will be no escape! ', '0', '0', '', 'Abandonner tout espoir! La <randomfaction> est revenue pour terminer ce qui avait été commencé il y a tant d\'années. Cette fois, il n\'y aura pas d\'échappatoire!', 'Gebt alle Hoffnung auf! Die <randomfaction> ist zurückgekehrt, um das zu vollenden, was vor so vielen Jahren begonnen wurde. Dieses Mal wird es kein Entkommen geben!', '', '', '¡Abandona toda esperanza! La <randomfaction> ha regresado para terminar lo que comenzó hace tantos años. ¡Esta vez no habrá escapatoria! ', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('659', 'taunt', 'Alert! You are marked for Extermination! ', '0', '0', '', 'Alerte! Vous êtes marqué pour l\'extermination!', 'Achtung! Du bist zur Auslöschung markiert!', '', '', '¡Alerta! ¡Estás marcado para el exterminio! ', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('660', 'taunt', 'The <subzone> is for guests only...', '0', '0', '', 'La <subzone> est réservée aux invités...', 'Die <subzone> ist nur für Gäste...', '', '', 'La <subzone> es solo para invitados...', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('661', 'taunt', 'Ha ha ha! You are hopelessly outmatched!', '0', '0', '', 'Hahaha! Vous êtes désespérément surpassé!', 'Ha ha ha! Ihr seid hoffnungslos unterlegen!', '', '', '¡Ja, ja, ja! ¡Estás irremediablemente superado!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('662', 'taunt', 'I will crush your delusions of grandeur! ', '0', '0', '', 'Je vais écraser vos illusions de grandeur!', 'Ich werde eure Größenwahnvorstellungen zerschmettern!', '', '', '¡Aplastaré tus delirios de grandeza! ', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('663', 'taunt', 'Forgive me, for you are about to lose the game.', '0', '0', '', 'Pardonnez-moi, car vous êtes sur le point de perdre la partie.', 'Vergib mir, denn du wirst das Spiel verlieren.', '', '', 'Perdóname, porque estás a punto de perder el juego.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('664', 'taunt', 'Struggling only makes it worse.', '0', '0', '', 'Lutter ne fait qu\'empirer les choses.', 'Sich zu wehren macht es nur schlimmer.', '', '', 'La lucha solo lo empeora.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('665', 'taunt', 'Vermin! Leeches! Take my blood and choke on it!', '0', '0', '', 'Vermine! sangsues ! Prends mon sang et étouffe-toi avec!', 'Ungeziefer! Blutegel! Nehmt mein Blut und erstickt daran!', '', '', '¡Alimañas! ¡Sanguijuelas! ¡Toma mi sangre y atragantate con ella!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('666', 'taunt', 'Not again... NOT AGAIN!', '0', '0', '', 'Pas encore... PAS ENCORE!', 'Nicht schon wieder... NICHT SCHON WIEDER!', '', '', 'No otra vez... ¡NO OTRA VEZ!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('667', 'taunt', 'My blood will be the end of you!', '0', '0', '', 'Mon sang sera ta fin!', 'Mein Blut wird euer Ende sein!', '', '', '¡Mi sangre será tu fin!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('668', 'taunt', 'Good, now you fight me!', '0', '0', '', 'Bien, maintenant tu me combats!', 'Gut, jetzt kämpfst du gegen mich!', '', '', 'Bien, ¡ahora pelea conmigo!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('669', 'taunt', 'Get da move on, guards! It be killin\' time!', '0', '0', '', 'Allez-y, gardes ! Ça va tuer le temps!', 'Bewegt euch, Wachen! Es ist Zeit zu töten!', '', '', '¡Muévanse, guardias! ¡Será para matar el tiempo!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('670', 'taunt', 'Don\'t be delayin\' your fate. Come to me now. I make your sacrifice quick.', '0', '0', '', 'Ne retardez pas votre destin. Viens à moi maintenant. Je fais votre sacrifice rapide.', 'Verzögert euer Schicksal nicht. Kommt jetzt zu mir. Ich mache euer Opfer schnell.', '', '', 'No demores tu destino. Ven a mí ahora. Hago que tu sacrificio sea rápido.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('671', 'taunt', 'You be dead soon enough!', '0', '0', '', 'Tu es mort bien assez tôt!', 'Ihr werdet bald tot sein!', '', '', '¡Estarás muerto lo suficientemente pronto!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('672', 'taunt', 'Mua-ha-ha!', '0', '0', '', 'Mua-ha-ha!', 'Mua-ha-ha!', '', '', '¡Mua-ja-ja!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('673', 'taunt', 'I be da predator! You da prey...', '0', '0', '', 'Je suis un prédateur ! Tu es une proie...', 'Ich bin der Jäger! Ihr seid die Beute...', '', '', '¡Soy un depredador! Eres presa...', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('674', 'taunt', 'You gonna leave in pieces!', '0', '0', '', 'Tu vas partir en morceaux!', 'Ihr werdet in Stücken gehen!', '', '', '¡Te vas a ir en pedazos!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('675', 'taunt', 'Death comes. Will your conscience be clear? ', '0', '0', '', 'La mort vient. Votre conscience sera-t-elle claire?', 'Der Tod kommt. Wird euer Gewissen rein sein?', '', '', 'La muerte llega. ¿Tu conciencia estará limpia? ', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('676', 'taunt', 'Your behavior will not be tolerated.', '0', '0', '', 'Votre comportement ne sera pas toléré.', 'Dein Verhalten wird nicht toleriert.', '', '', 'Tu comportamiento no será tolerado', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('677', 'taunt', 'The Menagerie is for guests only.', '0', '0', '', 'La Ménagerie est réservée aux invités.', 'Die Menagerie ist nur für Gäste.', '', '', 'The Menagerie es solo para invitados', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('678', 'taunt', 'Hmm, unannounced visitors, Preparations must be made... ', '0', '0', '', 'Hmm, visiteurs inopinés, il faut faire des préparatifs...', 'Hmm, unangemeldete Besucher, Vorbereitungen müssen getroffen werden...', '', '', 'Hmm, visitantes inesperados, se deben hacer preparativos... ', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('679', 'taunt', 'Hostile entities detected. Threat assessment protocol active. Primary target engaged. Time minus thirty seconds to re-evaluation.', '0', '0', '', 'Entités hostiles détectées. Protocole d\'évaluation de la menace actif. Cible principale engagée. Délai de réévaluation moins trente secondes.', 'Feindliche Einheiten entdeckt. Bedrohungsbewertung aktiv. Primärziel wird angegriffen. Zeit minus dreißig Sekunden bis zur Neubewertung.', '', '', 'Entidades hostiles detectadas. Protocolo de evaluación de amenazas activo. Objetivo principal comprometido. Tiempo menos treinta segundos para la reevaluación.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('680', 'taunt', 'New toys? For me? I promise I won\'t break them this time!', '0', '0', '', 'Nouveaux jouets? Pour moi? Promis je ne les casserai pas cette fois !', 'Neue Spielsachen? Für mich? Ich verspreche, ich werde sie diesmal nicht kaputt machen!', '', '', '¿Juguetes nuevos? ¿Para mi? ¡Te prometo que no los romperé esta vez!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('681', 'taunt', 'I\'m ready to play!', '0', '0', '', 'Je suis prêt à jouer!', 'Ich bin bereit zu spielen!', '', '', '¡Estoy listo para jugar!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('682', 'taunt', 'Shhh... it will all be over soon.', '0', '0', '', 'Chut... tout sera bientôt fini.', 'Pssst... es wird bald vorbei sein.', '', '', 'Shhh... todo terminará pronto.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('683', 'taunt', 'Aaaaaughibbrgubugbugrguburgle!', '0', '0', '', 'Aaaaaughibbrgubugbugrguburgle!', 'Aaaaaughibbrgubugbugrguburgle!', '', '', '¡Aaaaaughibbrgubugbugrguburgle!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('684', 'taunt', 'RwlRwlRwlRwl!', '0', '0', '', 'RwlRwlRwlRwl!', 'RwlRwlRwlRwl!', '', '', 'RwlRwlRwlRwl!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('685', 'taunt', 'You too, shall serve!', '0', '0', '', 'Toi aussi, tu serviras!', 'Auch du wirst dienen!', '', '', '¡Tú también, debes servir!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('686', 'taunt', 'Tell me... tell me everything!  Naughty secrets! I\'ll rip the secrets from your flesh!', '0', '0', '', 'Dis-moi... dis-moi tout ! Secrets coquins ! J\'arracherai les secrets de ta chair!', 'Erzähl mir... erzähl mir alles! Schmutzige Geheimnisse! Ich werde die Geheimnisse aus deinem Fleisch reißen!', '', '', 'Cuéntame... ¡cuéntame todo! ¡Secretos traviesos! ¡Arrancaré los secretos de tu carne!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('687', 'taunt', 'Prepare yourselves, the bells have tolled! Shelter your weak, your young and your old! Each of you shall pay the final sum! Cry for mercy, the reckoning has come!', '0', '0', '', 'Préparez-vous, les cloches ont sonné ! Mettez à l\'abri vos faibles, vos jeunes et vos vieux ! Chacun de vous paiera la somme finale ! Implorez la miséricorde , le jugement est venu!', 'Bereitet euch vor, die Glocken haben geläutet! Schützt eure Schwachen, eure Jungen und Alten! Jeder von euch wird den letzten Preis zahlen! Fleht um Gnade, die Abrechnung ist gekommen!', '', '', '¡Prepárense, las campanas han doblado! ¡Abriga a tus débiles, a tus jóvenes ya tus viejos! ¡Cada uno de ustedes pagará la suma final! Clama por misericordia, el ajuste de cuentas ha llegado!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('688', 'taunt', 'Where in Bonzo\'s brass buttons am I?', '0', '0', '', 'Où suis-je dans les boutons en laiton de Bonzo?', 'Wo in Bonzos Messingknöpfen bin ich?', '', '', '¿Dónde estoy en los botones de latón de Bonzo?', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('689', 'taunt', 'I can bear it no longer! Goblin King! Goblin King! Wherever you may be! Take this <target> far away from me!', '0', '0', '', 'Je ne peux plus le supporter ! Roi Gobelin ! Roi Gobelin ! Où que vous soyez ! Emmenez cette <target> loin de moi!', 'Ich kann es nicht länger ertragen! Goblinkönig! Goblinkönig! Wo immer du auch bist! Nimm dieses <target> weit weg von mir!', '', '', '¡No puedo soportarlo más! ¡Rey de los duendes! ¡Rey de los duendes! ¡WHERE quiera que estés! ¡Lleva a este <target> lejos de mí!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('690', 'taunt', 'You have thirteen hours in which to solve the labyrinth, before your baby brother becomes one of us... forever.', '0', '0', '', 'Vous avez treize heures pour résoudre le labyrinthe, avant que ton petit frère ne devienne l\'un des nôtres... pour toujours.', 'Du hast dreizehn Stunden Zeit, um das Labyrinth zu lösen, bevor dein kleiner Bruder einer von uns wird... für immer.', '', '', 'Tienes trece horas para resolver el laberinto, antes de que tu hermanito se convierta en uno de nosotros... para siempre', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('691', 'taunt', 'So, the <subzone> is a piece of cake, is it? Well, let\'s see how you deal with this little slice... ', '0', '0', '', 'Donc, la <subzone> est un jeu d\'enfant, n\'est-ce pas ? Eh bien, voyons comment tu gères cette petite tranche...', 'Also, das <subzone> ist ein Kinderspiel, ja? Nun, mal sehen, wie du mit diesem kleinen Stück zurechtkommst...', '', '', 'Entonces, la <subzone> es pan comido, ¿verdad? Bueno, veamos cómo lidias con esta pequeña porción... ', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('692', 'taunt', 'Back off, I\'ll take you on, headstrong to take on anyone, I know that you are wrong, and this is not where you belong', '0', '0', '', 'Reculez, je vais vous attaquer, têtu à affronter n\'importe qui, je sais que vous vous trompez, et ce n\'est pas votre place', 'Zurück, ich nehme dich auf, entschlossen, jeden herauszufordern, ich weiß, dass du falsch liegst, und dies ist nicht, wo du hingehörst.', '', '', 'Atrás, te enfrentaré, testarudo para enfrentar a cualquiera, sé que estás equivocado, y este no es el lugar al que perteneces', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('693', 'taunt', 'Show me whatcha got!', '0', '0', '', 'Montre-moi ce que tu as!', 'Zeig mir, was du hast!', '', '', '¡Muéstrame lo que tienes!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('694', 'taunt', 'To the death!', '0', '0', '', 'A la mort!', 'Bis zum Tod!', '', '', '¡Hasta la muerte!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('695', 'taunt', 'Twin blade action, for a clean close shave every time.', '0', '0', '', 'Action à double lame, pour un rasage de près propre à chaque fois.', 'Zwillingsklingenaktion, für eine saubere Rasur jedes Mal.', '', '', 'Acción de cuchilla doble, para un afeitado limpio y apurado en todo momento.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('696', 'taunt', 'Bring it on!', '0', '0', '', 'Allez-y!', 'Zeig, was du kannst!', '', '', '¡Adelante!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('697', 'taunt', 'You\'re goin\' down!', '0', '0', '', 'Tu descends!', 'Du wirst untergehen!', '', '', '¡Vas a caer!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('698', 'taunt', 'Stabby stab stab!', '0', '0', '', 'Coup de poignard poignardé!', 'Stech stech stech!', '', '', '¡Puñalada puñalada puñalada!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('699', 'taunt', 'Let\'s get this over quick, time is mana.', '0', '0', '', 'Finissons-en vite , le temps c\'est du mana.', 'Lass uns das schnell erledigen, Zeit ist Mana.', '', '', 'Terminemos con esto rápido, el tiempo es maná.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('700', 'taunt', 'I do not think you realise the gravity of your situation.', '0', '0', '', 'Je ne pense pas que tu te rendes compte de la gravité de ta situation.', 'Ich glaube nicht, dass du die Schwere deiner Lage begreifst.', '', '', 'No creo que te des cuenta de la gravedad de tu situación.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('701', 'taunt', 'I will bring honor to my family and my kingdom!', '0', '0', '', 'Je ferai honneur à ma famille et à mon royaume!', 'Ich werde meiner Familie und meinem Königreich Ehre bringen!', '', '', '¡Llevaré honor a mi familia y mi reino!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('702', 'taunt', 'Light, give me strength!', '0', '0', '', 'Lumière, donne-moi la force!', 'Licht, gib mir Stärke!', '', '', '¡Luz, dame fuerza!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('703', 'taunt', 'My church is the field of battle - time to worship...', '0', '0', '', 'Mon église est le champ de bataille - il est temps d\'adorer...', 'Mein Schlachtfeld ist meine Kirche – Zeit für den Gottesdienst...', '', '', 'Mi iglesia es el campo de batalla - hora de adorar...', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('704', 'taunt', 'I hold you in contempt...', '0', '0', '', 'Je te méprise...', 'Ich verachte dich...', '', '', 'Te tengo en desacato...', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('705', 'taunt', 'Face the hammer of justice!', '0', '0', '', 'Affrontez le marteau de la justice!', 'Stelle dich dem Hammer der Gerechtigkeit!', '', '', '¡Enfréntate al martillo de la justicia!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('706', 'taunt', 'Prove your worth in the test of arms under the Light!', '0', '0', '', 'Prouvez votre valeur dans l\'épreuve des armes sous la Lumière!', 'Beweise deinen Wert im Kampf unter dem Licht!', '', '', '¡Demuestra tu valía en la prueba de las armas bajo la Luz!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('707', 'taunt', 'All must fall before the might and right of my cause, you shall be next!', '0', '0', '', 'Tout doit tomber devant la force et le droit de ma cause, vous serez le prochain!', 'Alles muss vor der Macht und Gerechtigkeit meiner Sache fallen, du wirst der Nächste sein!', '', '', 'Todo debe caer ante el poder y el derecho de mi causa, ¡tú serás el próximo!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('708', 'taunt', 'Prepare to die!', '0', '0', '', 'Préparez-vous à mourir!', 'Bereite dich auf deinen Tod vor!', '', '', '¡Prepárate para morir!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('709', 'taunt', 'The beast with me is nothing compared to the beast within...', '0', '0', '', 'La bête avec moi n\'est rien comparée à la bête à l\'intérieur...', 'Das Biest bei mir ist nichts im Vergleich zu dem Biest in mir...', '', '', 'La bestia conmigo no es nada comparada con la bestia interior...', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('710', 'taunt', 'Witness the firepower of this fully armed huntsman!', '0', '0', '', 'Soyez témoin de la puissance de feu de ce chasseur entièrement armé!', 'Erlebt die Feuerkraft dieses voll bewaffneten Jägers!', '', '', '¡Sea testigo de la potencia de fuego de este cazador completamente armado!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('711', 'critical health', 'Heal me! Quick!', '0', '0', '', 'Soigne moi! Vite!', 'Heil mich! Schnell!', '', '', '¡Cúrame! ¡Rápido!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('712', 'critical health', 'Almost dead! Heal me!', '0', '0', '', 'Presque mort! Soigne moi!', 'Fast tot! Heil mich!', '', '', '¡Estoy casi muerto! ¡Cúrame!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('713', 'critical health', 'Help! Heal me!', '0', '0', '', 'Aider! Soigne moi!', 'Hilfe! Heil mich!', '', '', '¡Ayuda! ¡Cúrame!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('714', 'critical health', 'Somebody! Heal me!', '0', '0', '', 'Quelqu\'un! Soigne moi!', 'Jemand! Heil mich!', '', '', '¡Alguien! ¡Cúrame!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('715', 'critical health', 'Heal! Heal! Heal!', '0', '0', '', 'Soigner! Soigner! Soigner!', 'Heilen! Heilen! Heilen!', '', '', '¡Curame! ¡Saname! ¡Socorro!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('716', 'critical health', 'I am dying! Heal! Aaaaarhg!', '0', '0', '', 'Je meurs! Soigner! Aaaaarhg!', 'Ich sterbe! Heil mich! Aaaaarhg!', '', '', '¡Me estoy muriendo! ¡Saname! ¡Aaaaarhg!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('717', 'critical health', 'Heal me!', '0', '0', '', 'Soigne moi!', 'Heil mich!', '', '', '¡Cúrame!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('718', 'critical health', 'I will die. I will die. I will die. Heal!', '0', '0', '', 'Je vais mourir. Je vais mourir. Je vais mourir. Soigner!', 'Ich werde sterben. Ich werde sterben. Ich werde sterben. Heil!', '', '', 'Voy a morir. Voy a morir. Voy a morir. ¡Saname!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('719', 'critical health', 'Healers, where are you? I am dying!', '0', '0', '', 'Guérisseurs, où êtes-vous ? Je meurs!', 'Heiler, wo seid ihr? Ich sterbe!', '', '', 'Sanadores, ¿dónde estais? ¡Me estoy muriendo!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('720', 'critical health', 'Oh the pain. Heal me quick!', '0', '0', '', 'Ah la douleur. Guéris-moi vite!', 'Oh der Schmerz. Heil mich schnell!', '', '', 'Ouch, qué dolor. ¡Cúrame rápido!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('721', 'low health', 'Need heal', '0', '0', '', 'Besoin de guérir', 'Brauche Heilung', '', '', 'Necesito una cura', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('722', 'low health', 'Low health', '0', '0', '', 'Santé faible', 'Wenig Gesundheit', '', '', 'Salud baja', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('723', 'low health', 'Drop a heal. Please.', '0', '0', '', 'Dépose un soin. S\'il te plaît.', 'Gib mir eine Heilung. Bitte.', '', '', 'Una sanación por favor.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('724', 'low health', 'Could somebody drop a heal on me?', '0', '0', '', 'Quelqu\'un pourrait-il me soigner?', 'Könnte jemand eine Heilung auf mich wirken?', '', '', '¿Alguien podría curarme?', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('725', 'low health', 'Hey! Better heal me now than rez later', '0', '0', '', 'Hey! Mieux vaut me soigner maintenant que rez plus tard', 'Hey! Lieber jetzt heilen als später wiederbeleben.', '', '', '¡Oye! Mejor curarme ahora que resucitarme después', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('726', 'low health', 'I am sorry. Need another heal', '0', '0', '', 'Je suis désolé. J\'ai besoin d\'un autre soin', 'Es tut mir leid. Ich brauche noch eine Heilung.', '', '', 'Lo siento. Necesito otra curación', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('727', 'low health', 'Damn mobs. Heal me please', '0', '0', '', 'Maudits mobs. Guéris moi s\'il te plait', 'Verdammte Mobs. Bitte heil mich.', '', '', '¡Malditos bichos! ¡Una curita por favor!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('728', 'low health', 'One more hit and I am done for. Heal please', '0', '0', '', 'Un coup de plus et c\'est fini. Guéris moi s\'il te plait', 'Ein weiterer Treffer und ich bin erledigt. Bitte heil mich.', '', '', 'Un golpe más y estoy acabado. Cura por favor', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('729', 'low health', 'Are there any healers?', '0', '0', '', 'Y a-t-il des guérisseurs?', 'Gibt es hier Heiler?', '', '', '¿Hay sanadores?', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('730', 'low health', 'Why do they always punch me in the face? Need heal', '0', '0', '', 'Pourquoi me frappent-ils toujours au visage? Besoin de soins', 'Warum schlagen sie mir immer ins Gesicht? Brauche Heilung.', '', '', '¿Por qué siempre me golpean en la cara? Necesito sanacion', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('731', 'low health', 'Can anybody heal me a bit?', '0', '0', '', 'Quelqu\'un peut-il me guérir un peu?', 'Kann mich jemand ein bisschen heilen?', '', '', '¿Alguien puede curarme un poco?', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('732', 'low mana', 'OOM', '0', '0', '', 'MOO', 'OOM', '', '', 'No tengo mana!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('733', 'low mana', 'I am out of mana', '0', '0', '', 'je n\'ai plus de mana', 'Ich habe kein Mana mehr.', '', '', 'No tengo maná', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('734', 'low mana', 'Damn I wasted all my mana on this', '0', '0', '', 'Putain j\'ai gaspillé tout mon mana sur ça', 'Verdammt, ich habe mein ganzes Mana dafür verschwendet.', '', '', 'Me cago en todo! Malgasté todo mi maná enseguida', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('735', 'low mana', 'You should wait until I drink or regenerate my mana', '0', '0', '', 'Vous devriez attendre que je boive ou que je régénère mon mana', 'Ihr solltet warten, bis ich trinke oder mein Mana regeneriere.', '', '', 'Deberías esperar hasta que beba o regenere mi maná', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('736', 'low mana', 'Low mana', '0', '0', '', 'Mana faible', 'Wenig Mana', '', '', 'Maná bajo', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('737', 'low mana', 'No mana. Again?', '0', '0', '', 'Pas de mana. De nouveau?', 'Kein Mana. Schon wieder?', '', '', 'Sin maná. ¿Otra vez?', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('738', 'low mana', 'Low mana. Wanna drink', '0', '0', '', 'Mana faible. Je veux boire', 'Wenig Mana. Will trinken.', '', '', 'Maná bajo. Quiero beber', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('739', 'low mana', 'Do we have a vending machine? Out of mana again', '0', '0', '', 'Avons-nous un distributeur automatique? Plus de mana à nouveau', 'Haben wir einen Automaten? Schon wieder kein Mana.', '', '', '¿Tenemos una máquina expendedora? Sin maná otra vez', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('740', 'low mana', 'My mana is history', '0', '0', '', 'Mon mana appartient à l\'histoire', 'Mein Mana ist Geschichte.', '', '', 'Mi maná es historia', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('741', 'low mana', 'I\'d get some drinks next time. Out of mana', '0', '0', '', 'Je prendrais quelques verres la prochaine fois. Manque de mana', 'Ich hole mir nächstes Mal Getränke. Kein Mana mehr.', '', '', '¡No tengo maná! Tengo que comprar bebidas la próxima vez...', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('742', 'low mana', 'Where is my mana?', '0', '0', '', 'Où est mon mana?', 'Wo ist mein Mana?', '', '', '¿Dónde está mi maná?', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('743', 'low ammo', 'I have few <ammo> left!', '0', '0', '', 'Il me reste peu de <ammo>!', 'Ich habe nur noch wenig <ammo>!', '', '', '¡Me quedan pocas <ammo>!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('744', 'low ammo', 'I need more <ammo>!', '0', '0', '', 'J\'ai besoin de plus de <ammo>!', 'Ich brauche mehr <ammo>!', '', '', '¡Necesito más <ammo>!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('745', 'low ammo', '100 <ammo> left!', '0', '0', '', 'Il reste 100 <ammo>!', '100 <ammo> übrig!', '', '', '¡Quedan 100 <ammo>!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('746', 'no ammo', 'That\'s it! No <ammo>!', '0', '0', '', 'C\'est ça! Pas de <ammo>!', 'Das war\'s! Kein <ammo> mehr!', '', '', '¡Eso es todo! ¡Sin <ammo>!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('747', 'no ammo', 'And you have my bow... Oops, no <ammo>!', '0', '0', '', 'Et vous avez mon arc... Oups, pas de <ammo>!', 'Und ihr habt meinen Bogen... Ups, kein <ammo>!', '', '', 'Y tú tienes mi arco... ¡Uy, sin <ammo>!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('748', 'no ammo', 'Need ammo!', '0', '0', '', 'Besoin de munitions!', 'Brauche Munition!', '', '', '¡Necesito munición!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('749', 'aoe', 'Oh god!', '0', '0', '', 'Oh mon Dieu!', 'Oh Gott!', '', '', '¡Oh, Dios!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('750', 'aoe', 'I am scared', '0', '0', '', 'j\'ai peur', 'Ich habe Angst.', '', '', 'Tengo miedo', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('751', 'aoe', 'We are done for', '0', '0', '', 'Nous avons fini pour', 'Wir sind erledigt.', '', '', 'Hemos terminado', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('752', 'aoe', 'This is over', '0', '0', '', 'C\'est terminé', 'Das war\'s.', '', '', 'Esto se acabó', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('753', 'aoe', 'This ends now', '0', '0', '', 'Cela se termine maintenant', 'Das endet jetzt.', '', '', 'Esto termina ahora', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('754', 'aoe', 'Could somebody cast blizzard or something?', '0', '0', '', 'Quelqu\'un pourrait-il lancer le blizzard ou quelque chose comme ça?', 'Könnte jemand Blizzard oder etwas Ähnliches zaubern?', '', '', '¿Alguien podría lanzar ventisca o algo así?', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('755', 'aoe', 'Damn. The tank aggroed all the mobs around', '0', '0', '', 'Mince. Le tank a agro toutes les mobs autour', 'Verdammt. Der Tank hat alle Mobs in der Nähe gepullt.', '', '', '¡Me cago en todo! El tanque atrajo a todos los mobs...', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('756', 'aoe', 'We gonna die. We gonna die. We gonna die.', '0', '0', '', 'Nous allons mourir. Nous allons mourir. Nous allons mourir.', 'Wir werden sterben. Wir werden sterben. Wir werden sterben.', '', '', 'Vamos a morir. Vamos a morir. Vamos a morir.', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('757', 'aoe', 'Whoa! So many toys to play with', '0', '0', '', 'Ouah ! Tant de jouets avec lesquels jouer', 'Whoa! So viele Spielzeuge zum Spielen.', '', '', '¡Vaya! Tantos juguetes con los que jugar', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('758', 'aoe', 'I gonna kill them all!', '0', '0', '', 'Je vais tous les tuer!', 'Ich werde sie alle töten!', '', '', '¡Voy a matarlos a todos!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('759', 'aoe', 'If the tank dies we are history', '0', '0', '', 'Si le tank meurt, nous appartenons à l\'histoire', 'Wenn der Tank stirbt, sind wir Geschichte.', '', '', 'Si el tanque muere somos historia', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('760', 'aoe', 'Aaaaaargh!', '0', '0', '', 'Aaaaaargh!', 'Aaaaaargh!', '', '', '¡Aaaaaargh!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('761', 'aoe', 'LEEEEERROOOYYYYYYYYYYYY JENNKINNNSSSSSS!!!!!!!', '0', '0', '', 'LEEEEERROOOYYYYYYYYYYYY JENNKINNNSSSSSS!!!!!!!', 'LEEEEERROOOYYYYYYYYYYYY JENNKINNNSSSSSS!!!!!!!', '', '', 'LEEEEERROOOYYYYYYYYYYYY JENNKINNNSSSSSS!!!!!!!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('762', 'aoe', 'Right. What do we have in AOE?', '0', '0', '', 'D\'accord. Qu\'avons-nous en dégats de zone?', 'Okay. Was haben wir an AOE?', '', '', 'Claro. ¿Qué tenemos en AOE?', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('763', 'aoe', 'This gets interesting', '0', '0', '', 'Cela devient intéressant', 'Das wird interessant.', '', '', 'Esto se pone interesante', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('764', 'aoe', 'Cool. Get them in one place for a good flamestrike', '0', '0', '', 'Cool. Rassemblez-les au même endroit pour un bon coup de flamme', 'Cool. Bringt sie an einen Ort für einen guten Flammenstoß.', '', '', 'Genial! Ponlos todos juntos para un buen ataque en area', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('765', 'aoe', 'Kill! Kill! Kill!', '0', '0', '', 'Tuer! Tuer! Tuer!', 'Töten! Töten! Töten!', '', '', '¡Matar! ¡Matar! ¡Matar!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('766', 'aoe', 'I think my pants are wet', '0', '0', '', 'Je pense que mon pantalon est mouillé', 'Ich glaube, meine Hose ist nass.', '', '', 'Creo que mis pantalones están mojados', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('767', 'aoe', 'We are history', '0', '0', '', 'Nous sommes l\'histoire', 'Wir sind Geschichte.', '', '', 'Somos historia', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('768', 'aoe', 'I hope healers are ready. Leeeeroy!', '0', '0', '', 'J\'espère que les guérisseurs sont prêts. Leeeeeroy!', 'Ich hoffe, die Heiler sind bereit. Leeeeroy!', '', '', 'Espero que los sanadores estén listos. ¡Leeeroy!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('769', 'aoe', 'I hope they won\'t come for me', '0', '0', '', 'j\'espère qu\'ils ont gagné, qu\'ils ne viendront pas pour moi', 'Ich hoffe, sie kommen nicht zu mir.', '', '', 'Espero que no vengan por mí', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('770', 'aoe', 'Oh no. I can\'t see at this slaugther', '0', '0', '', 'Oh non. Je ne peux pas voir à ce massacre', 'Oh nein. Ich kann dieses Gemetzel nicht ansehen.', '', '', 'Oh, no. No puedo ver esta matanza', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('771', 'loot', 'I hope there will be some money', '0', '0', '', 'j\'espère qu\'il y aura de l\'argent', 'Ich hoffe, es gibt etwas Geld.', '', '', 'Espero que haya algo de dinero...', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('772', 'loot', 'Loot! Loot!', '0', '0', '', 'Butin! Butin!', 'Beute! Beute!', '', '', '¡Botín! ¡Botín!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('773', 'loot', 'My precious', '0', '0', '', 'Mon précieux', 'Mein Schatz.', '', '', 'Mi tesoro...', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('774', 'loot', 'I hope there is a shiny epic item waiting for me there', '0', '0', '', 'J\'espère qu\'il y a un objet épique brillant qui m\'attend ici', 'Ich hoffe, da wartet ein glänzendes episches Item auf mich.', '', '', 'Espero que haya un objeto épico brillante esperándome allí', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('775', 'loot', 'I have deep pockets and bags', '0', '0', '', 'J\'ai des poches et des sacs profonds', 'Ich habe tiefe Taschen und Beutel.', '', '', 'Tengo bolsillos profundos y infinitos', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('776', 'loot', 'All is mine!', '0', '0', '', 'Tout est à moi!', 'Alles gehört mir!', '', '', '¡Todo es mío!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('777', 'loot', 'Hope no gray loot today', '0', '0', '', 'J\'espère pas de merde grise aujourd\'hui', 'Hoffentlich heute kein grauer Loot.', '', '', 'Espero que hoy no haya mierda gris', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('778', 'loot', 'This loot is MINE!', '0', '0', '', 'Ce butin est à MOI!', 'Diese Beute gehört MIR!', '', '', '¡Este botín es MÍO!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('779', 'loot', 'Looting is disgusting but I need money', '0', '0', '', 'Le pillage est dégoûtant mais j\'ai besoin d\'argent', 'Looten ist widerlich, aber ich brauche Geld.', '', '', 'El saqueo es repugnante pero necesito dinero...', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('780', 'loot', 'Gold!', '0', '0', '', 'Or!', 'Gold!', '', '', '¡Oro!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('781', 'loot', 'OK. Let\'s see what they\'ve got', '0', '0', '', 'D\'ACCORD. Voyons ce qu\'ils ont', 'Okay. Mal sehen, was sie haben.', '', '', 'OK. Veamos qué tienen', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('782', 'loot', 'Do not worry. I will loot eveything', '0', '0', '', 'Ne t\'inquiète pas. je vais tout piller', 'Keine Sorge. Ich werde alles looten.', '', '', 'No te preocupes. Saquearé todo', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('783', 'loot', 'I am loot ninja', '0', '0', '', 'je suis un ninja de butin', 'Ich bin ein Loot-Ninja.', '', '', 'Soy un ladron de tesoros', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('784', 'loot', 'Do I neeed to roll?', '0', '0', '', 'Dois-je recommencer?', 'Muss ich würfeln?', '', '', '¿Necesito lanzar dados?', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('785', 'loot', 'Somebody explain me, where they did put all this stuff?', '0', '0', '', 'Quelqu\'un m\'explique, où ils ont mis tout ça?', 'Kann mir jemand erklären, wo sie das ganze Zeug gelassen haben?', '', '', 'Alguien me explica, ¿dónde pusieron todas estas cosas?', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('786', 'loot', 'No, I won\'t loot gray crap', '0', '0', '', 'Non, je ne pillerai pas la merde grise', 'Nein, ich plündere keinen grauen Mist.', '', '', 'No, no saquearé mierda gris', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('787', 'loot', 'I\'m first. I\'m first. I\'m first.', '0', '0', '', 'Je suis le premier. Je suis le premier. Je suis le premier.', 'Ich bin der Erste. Ich bin der Erste. Ich bin der Erste.', '', '', '¡Es mio! ¡Es mio! ¡Es mio!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('788', 'loot', 'Give me your money!', '0', '0', '', 'Donne-moi ton argent!', 'Gib mir dein Geld!', '', '', '¡Dame todo tu dinero!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('789', 'loot', 'My pockets are empty, I need to fill them', '0', '0', '', 'Mes poches sont vides, j\'ai besoin de les remplir', 'Meine Taschen sind leer, ich muss sie füllen.', '', '', 'Mis bolsillos están vacíos y necesitan llenarse!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('790', 'loot', 'I\'ve got a new bag for this', '0', '0', '', 'J\'ai un nouveau sac pour ça', 'Ich habe dafür eine neue Tasche.', '', '', 'Tengo una nueva bolsa para esto', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('791', 'loot', 'I hope I won\'t aggro anybody while looting', '0', '0', '', 'J\'espère que je n\'agresserai personne pendant le pillage', 'Ich hoffe, ich ziehe niemanden während des Lootens.', '', '', 'Espero no ofender a nadie mientras saqueo', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('792', 'loot', 'Please don\'t watch. I am looting', '0', '0', '', 'S\'il vous plaît, ne regardez pas. je pille', 'Bitte nicht zuschauen. Ich loote.', '', '', 'Por favor, no mires. Estoy saqueando', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('793', 'loot', 'Ha! You won\'t get any piece of it!', '0', '0', '', 'Ha! Vous n\'en aurez aucun morceau!', 'Ha! Ihr bekommt nichts davon!', '', '', '¡Ja! ¡No obtendrás nada de eso!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('794', 'loot', 'Looting is cool', '0', '0', '', 'Le pillage c\'est cool', 'Looten ist cool.', '', '', 'Saquear es genial', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('795', 'loot', 'I like new gear', '0', '0', '', 'j\'aime le nouveau matos', 'Ich mag neue Ausrüstung.', '', '', 'Me gusta el equipo nuevo', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('796', 'loot', 'I\'l quit if there is nothing valuable again', '0', '0', '', 'J\'arrêterai s\'il n\'y a plus rien de précieux', 'Ich höre auf, wenn wieder nichts Wertvolles dabei ist.', '', '', 'Me doy por vencido si no hay nada util', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('797', 'loot', 'I hope it is be a pretty ring', '0', '0', '', 'j\'espère que c\'est une jolie bague', 'Ich hoffe, es ist ein hübscher Ring.', '', '', 'Espero que sea un anillo bonito', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('798', 'loot', 'I\'l rip the loot from you', '0', '0', '', 'Je t\'arracherai le butin', 'Ich reiße dir die Beute aus den Händen.', '', '', 'Te arrancaré el botín', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('799', 'loot', 'Everybody stay off. I\'m going to loot', '0', '0', '', 'Tout le monde reste à l\'écart. je vais piller', 'Alle wegbleiben. Ich werde looten.', '', '', '¡Alejaos todos! Voy a lootear', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('800', 'loot', 'Sweet loot', '0', '0', '', 'Doux butin', 'Süße Beute.', '', '', 'Dulce botín', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('801', 'loot', 'The Roll God! Give me an epic today', '0', '0', '', 'Le Dieu du rouleau ! Donnez-moi de l\'épique aujourd\'hui', 'Die Würfelgötter! Gib mir heute ein episches Item.', '', '', '¡El Dios de los dados! Dame un epico hoy', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('802', 'loot', 'Please give me new toys', '0', '0', '', 'S\'il te plaît, donne-moi de nouveaux jouets', 'Bitte gib mir neue Spielzeuge.', '', '', 'Por favor, dame nuevos juguetes', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('803', 'loot', 'I hope they carry tasties', '0', '0', '', 'J\'espère qu\'ils portent des saveurs', 'Ich hoffe, sie haben Leckereien dabei.', '', '', 'Espero que caiga algo sabrosos', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('804', 'loot', 'The gold is mine. I\'l leave everyting, I promise', '0', '0', '', 'L\'or est à moi. Je laisse tout, je promets', 'Das Gold gehört mir. Ich lasse alles andere liegen, ich verspreche es.', '', '', 'El oro es mío. Dejaré todo lo demas, lo prometo!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('805', 'loot', 'No, I can\'t resist', '0', '0', '', 'Non, je ne peux pas résister', 'Nein, ich kann nicht widerstehen.', '', '', 'No, no puedo resistir', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('806', 'loot', 'I want more!', '0', '0', '', 'Je veux plus!', 'Ich will mehr!', '', '', '¡Quiero más!', '', '');
INSERT INTO `ai_playerbot_texts_german` VALUES ('807', 'wait_travel_close', 'I am close, wait for me!', '0', '0', '', '', 'Ich bin nah dran, wartet auf mich!', '', '', '¡Estoy cerca, espérame!', '', 'Я тут рядом, подожди!');
INSERT INTO `ai_playerbot_texts_german` VALUES ('808', 'wait_travel_close', 'I\'m not far, please wait!', '0', '0', '', '', 'Ich bin nicht weit, bitte wartet!', '', '', 'No estoy lejos, ¡esperame por favor!', '', 'Я недалеко, погодите!');
